     1095:        (info_ptr->valid & PNG_INFO_pHYs) != 0)
     1096:    {
     1097:       if (res_x != NULL)
     1098:       {
     1099:          *res_x = info_ptr->x_pixels_per_unit;
     1100:          retval |= PNG_INFO_pHYs;
     1101:       }
     1102: 
